'use strict';
const $=s=>document.querySelector(s),A=RepoAccount,P=RepoProviders,S=RepoStore,Q=RepoQuality;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],repos=[],repoMap=new Map(),editing=null,selected=[],started=false,busy=false,activeTab='editorial';
const message=(text,error=false)=>{$('#admin-message').textContent=text;$('#admin-message').classList.toggle('error',error)};
function gate(){if(!A.ready)return;if(!A.user?.admin){started=false;rows=[];editing=null;selected=[];$('#admin-workspace').hidden=true;$('#admin-gate').hidden=false;$('#admin-gate').innerHTML=`<p class="eyebrow">ADMINISTRATION</p><h1>${A.user?'Administrator access required':A.enabled?'Sign in to your workspace':'Administration is being set up'}</h1><p>${A.user?'Your account can save likes. Storefront editing and analytics require an administrator role.':A.enabled?'Use the GitHub account that has been granted administrator access.':'The storefront is available while account setup is completed.'}</p>${!A.user&&A.enabled?'<a class="button lime" href="/api/auth?action=start&return=%2Fadmin.html">Sign in with GitHub ↗</a>':''}<a class="button outline" href="/">Back to the store</a>`;return}$('#admin-gate').hidden=true;$('#admin-workspace').hidden=false;if(!started){started=true;void initialize()}}
async function initialize(){message('Loading your workspace…');try{const [data,catalog,spaces]=await Promise.all([A.request('/api/editorial?manage=1'),fetch('/catalog.json').then(r=>r.json()),fetch('/spaces.json').then(r=>r.json())]);rows=data.rows;repos=P.mergeCatalog(catalog.repositories||[],spaces.repositories||[]).filter(r=>r.availability!=='unavailable');repoMap=new Map(repos.map(r=>[r.full,r]));$('#custom-rows').checked=data.customRows;$('#row-category').innerHTML='<option value="">Any category</option>'+[...new Set(repos.map(r=>r.category).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('');renderRows();reset();message('')}catch(e){message(e.message,true)}}
async function reload(){const data=await A.request('/api/editorial?manage=1');rows=data.rows;$('#custom-rows').checked=data.customRows;renderRows()}
function renderRows(){$('#row-list').innerHTML=rows.length?rows.map((row,i)=>`<article class="row-tile"><h3>${esc(row.title)}</h3><p>${row.enabled?'Published':'Draft'} · ${row.mode==='manual'?`${row.items.length} selected projects`:esc(row.mode)}${row.category?' · '+esc(row.category):''}</p><div class="row-tile-actions"><button data-edit="${row.id}">Edit</button><button data-move="${row.id}" data-step="-1" aria-label="Move ${esc(row.title)} up" ${i===0?'disabled':''}>↑</button><button data-move="${row.id}" data-step="1" aria-label="Move ${esc(row.title)} down" ${i===rows.length-1?'disabled':''}>↓</button><button data-publish="${row.id}">${row.enabled?'Unpublish':'Publish'}</button><button data-delete="${row.id}">Delete</button></div></article>`).join(''):'<p class="small">Create your first category row. Start with a draft and publish when it is ready.</p>'}
function reset(){editing=null;selected=[];$('#row-form').reset();$('#editor-title').textContent='Create a row';$('#row-state').textContent='Draft';renderSelection();searchProjects();updateMode()}
function edit(row){editing={...row};selected=[...row.items];$('#editor-title').textContent='Edit row';$('#row-title').value=row.title;$('#row-description').value=row.description;$('#row-category').value=row.category;$('#row-mode').value=row.mode;$('#row-enabled').checked=row.enabled;$('#row-state').textContent=row.enabled?'Published':'Draft';renderSelection();searchProjects();updateMode();$('#row-title').focus()}
function values(){return {id:editing?.id,revision:editing?.revision,title:$('#row-title').value,description:$('#row-description').value,category:$('#row-category').value,mode:$('#row-mode').value,enabled:$('#row-enabled').checked,items:selected}}
function renderSelection(){$('#selection-count').textContent=`${selected.length} selected` ;$('#selected-projects').innerHTML=selected.length?selected.map((id,i)=>`<div class="selected-project"><span>${esc(repoMap.get(id)?.name||id)}<small>${esc(id)}${!repoMap.has(id)?' · Unavailable; remove before saving':''}</small></span><button data-selected-move="${i}" data-step="-1" aria-label="Move ${esc(id)} up" ${i===0?'disabled':''}>↑</button><button data-selected-move="${i}" data-step="1" aria-label="Move ${esc(id)} down" ${i===selected.length-1?'disabled':''}>↓</button><button data-remove="${i}" aria-label="Remove ${esc(id)}">×</button></div>`).join(''):'<p class="small">Choose the projects that belong on this shelf.</p>'}
function searchProjects(){const words=$('#project-search').value.toLowerCase().trim().split(/\s+/).filter(Boolean),category=$('#row-category').value;const matches=repos.filter(r=>(!category||r.category===category)&&words.every(word=>[r.name,r.full,r.description,...S.technologies(r)].join(' ').toLowerCase().includes(word)));$('#project-results').innerHTML=matches.slice(0,30).map(r=>`<button type="button" class="project-choice" data-select="${esc(r.full)}" ${selected.includes(r.full)?'disabled':''}><strong>${esc(r.name)}</strong><small>${esc(r.category)} · ${esc(r.full)}${Q.hasLiveDemo(r)?' · Demo':''}</small></button>`).join('')||'<p class="small">No matching projects.</p>'}
function updateMode(){const manual=$('#row-mode').value==='manual';$('#manual-selection').hidden=!manual;$('#automatic-note').hidden=manual}
async function task(fn){if(busy)return;busy=true;$('#save-row').disabled=true;try{await fn()}catch(e){message(e.message,true);if(e.status===409)await reload();if(e.status===401||e.status===403)await A.refresh()}finally{busy=false;$('#save-row').disabled=false}}
$('#row-form').onsubmit=e=>{e.preventDefault();void task(async()=>{message('Saving row…');const data=await A.request('/api/editorial',{method:'POST',body:JSON.stringify({row:values()})});await reload();edit(data.row);message(data.row.enabled?'Published. The row is available on the storefront.':'Draft saved.')})};
$('#new-row').onclick=reset;$('#reset-row').onclick=reset;$('#project-search').oninput=searchProjects;$('#row-category').onchange=searchProjects;$('#row-mode').onchange=updateMode;$('#row-enabled').onchange=()=>$('#row-state').textContent=$('#row-enabled').checked?'Ready to publish':'Draft';
$('#custom-rows').onchange=e=>void task(async()=>{await A.request('/api/editorial',{method:'POST',body:JSON.stringify({action:'settings',customRows:e.target.checked})});message(e.target.checked?'Custom category rows enabled.':'Automatic category rows restored.')});
$('#admin-signout').onclick=()=>void A.signout().catch(e=>message(e.message,true));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.adminTab){activeTab=b.dataset.adminTab;$('#editorial-panel').hidden=activeTab!=='editorial';$('#analytics-panel').hidden=activeTab!=='analytics';document.querySelectorAll('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===b));if(activeTab==='analytics')void loadAnalytics();return}if(b.dataset.select){if(selected.length>=120){message('This row can contain up to 120 selected projects.',true);return}selected.push(b.dataset.select);renderSelection();searchProjects();return}if(b.dataset.remove!==undefined){selected.splice(Number(b.dataset.remove),1);renderSelection();searchProjects();return}if(b.dataset.selectedMove!==undefined){const i=Number(b.dataset.selectedMove),j=i+Number(b.dataset.step);[selected[i],selected[j]]=[selected[j],selected[i]];renderSelection();return}if(b.dataset.edit){edit(rows.find(r=>r.id===b.dataset.edit));return}if(b.dataset.move)void task(async()=>{const i=rows.findIndex(r=>r.id===b.dataset.move),j=i+Number(b.dataset.step),ids=rows.map(r=>r.id);[ids[i],ids[j]]=[ids[j],ids[i]];await A.request('/api/editorial',{method:'POST',body:JSON.stringify({action:'reorder',ids})});await reload();if(editing)editing={...rows.find(r=>r.id===editing.id)};message('Row order updated.')});if(b.dataset.publish)void task(async()=>{const row=rows.find(r=>r.id===b.dataset.publish);await A.request('/api/editorial',{method:'POST',body:JSON.stringify({row:{...row,enabled:!row.enabled}})});await reload();message(row.enabled?'Row unpublished.':'Row published.')});if(b.dataset.delete){const row=rows.find(r=>r.id===b.dataset.delete);if(confirm(`Delete the “${row.title}” row? Projects remain in the catalog.`))void task(async()=>{await A.request('/api/editorial',{method:'DELETE',body:JSON.stringify({id:row.id,revision:row.revision})});if(editing?.id===row.id)reset();await reload();message('Row deleted.')})}});
function metric(value,label){return `<div class="metric"><strong>${Number(value||0).toLocaleString()}</strong><span>${esc(label)}</span></div>`}
function chart(data,key,label){if(!data.length)return '<p class="chart-empty">History will appear as refreshes complete.</p>';const values=data.map(r=>Number(r[key]||0)),min=Math.min(...values),max=Math.max(...values),range=max-min||1;const points=values.map((v,i)=>`${20+i/Math.max(1,values.length-1)*660},${145-(v-min)/range*115}`).join(' ');return `<svg viewBox="0 0 700 175" role="img" aria-label="${esc(label)}: ${values[0]} to ${values.at(-1)}"><path d="M20 145H680" stroke="#3a482f"/><polyline fill="none" stroke="#c6ec88" stroke-width="3" stroke-linejoin="round" points="${points}"/>${data.map((r,i)=>`<circle cx="${20+i/Math.max(1,values.length-1)*660}" cy="${145-(values[i]-min)/range*115}" r="4" fill="#c6ec88"><title>${esc(r.day||r.at)}: ${values[i].toLocaleString()}</title></circle>`).join('')}</svg><div class="chart-axis"><span>${esc((data[0].day||data[0].at).slice(0,10))}</span><span>${esc((data.at(-1).day||data.at(-1).at).slice(0,10))}</span></div>`}
let analyticsToken=0;
async function loadAnalytics(){const token=++analyticsToken;$('#analytics-content').innerHTML='<p class="loading-note">Loading activity…</p>';try{const days=Number($('#analytics-range').value),data=await A.request('/api/analytics?days='+days);if(token!==analyticsToken)return;const daily=data.daily||[],total=key=>daily.reduce((n,r)=>n+Number(r[key]||0),0);const cutoff=Date.now()-days*86400000,growth=(data.growth||[]).filter(r=>Date.parse(r.at)>=cutoff);$('#analytics-content').innerHTML=`${!data.trackingEnabled?'<p class="analytics-caption">Visit tracking is awaiting activation. Catalog coverage is available below.</p>':''}<div class="metric-grid">${metric(total('visits'),'Visits')}${metric(total('page_views'),'Page views')}${metric(total('listing_views'),'Listing views')}${metric(total('demo_clicks'),'Demo clicks')}${metric(total('fork_clicks'),'Fork / duplicate clicks')}${metric(total('searches'),'Searches')}${metric(data.totalLikes,'Current saved likes')}${metric(data.likesAdded,'Likes added and still saved')}</div><div class="analytics-grid"><section class="analytics-box"><h3>Page views over time</h3>${chart(daily,'page_views','Page views')}<p class="analytics-caption">${esc(data.visitorMethod)}</p><details><summary>Daily counts</summary><table class="analytics-table"><thead><tr><th>Date (UTC)</th><th>Visits</th><th>Views</th><th>Visitors</th></tr></thead><tbody>${daily.map(r=>`<tr><td>${r.day}</td><td>${r.visits}</td><td>${r.page_views}</td><td>${r.visitors}</td></tr>`).join('')}</tbody></table></details></section><section class="analytics-box"><h3>Most viewed projects</h3>${data.topListings?.length?`<table class="analytics-table"><thead><tr><th>Project</th><th>Views</th></tr></thead><tbody>${data.topListings.map(r=>`<tr><td>${esc(repoMap.get(r.project_id)?.name||r.project_id)}</td><td>${Number(r.views).toLocaleString()}</td></tr>`).join('')}</tbody></table>`:'<p class="chart-empty">Listing views will appear here.</p>'}</section></div><section class="analytics-box"><h3>Library growth</h3><div class="metric-grid">${metric(data.coverage.availableProjects,'Available projects')}${metric(data.coverage.withDemo,'With demos')}${metric(data.coverage.readmesSaved,'Saved READMEs')}${metric(data.coverage.supportingContextsSaved,'Supporting contexts')}</div>${chart(growth,'records','Indexed projects')}<details><summary>Catalog snapshots</summary><table class="analytics-table"><thead><tr><th>Date (UTC)</th><th>Projects</th><th>Demos</th><th>Previews</th><th>Unavailable</th></tr></thead><tbody>${growth.slice(-30).map(r=>`<tr><td>${esc(r.at.slice(0,16).replace('T',' '))}</td><td>${r.records}</td><td>${r.withDemo}</td><td>${r.withScreenshot}</td><td>${r.unavailable}</td></tr>`).join('')}</tbody></table></details><p class="analytics-caption">Growth history starts with this update and is saved after each catalog refresh. Fork clicks represent intent, not a confirmed fork. No search text or IP addresses are stored. Daily totals remain; detailed activity is retained for 90 days.</p></section>`}catch(e){if(token===analyticsToken)$('#analytics-content').innerHTML=`<p class="loading-note">${esc(e.message)}</p>`;if(e.status===401||e.status===403)await A.refresh()}}
$('#analytics-range').onchange=()=>void loadAnalytics();window.addEventListener('reposhelf-account',gate);gate();
